import{_ as a,o,c as l,al as r}from"./chunks/framework.BfjwFeD9.js";const m=JSON.parse('{"title":"Packages","description":"","frontmatter":{"outline":"deep","head":[["meta",{"name":"og:title","content":"Packages | ProzillaOS Docs"}],["meta",{"name":"twitter:title","content":"Packages | ProzillaOS Docs"}],["meta",{"name":"og:description","content":"Documentation for ProzillaOS and its packages."}],["meta",{"name":"twitter:description","content":"Documentation for ProzillaOS and its packages."}],["link",{"rel":"canonical","href":"https://os.prozilla.dev/docs/reference/packages"}],["meta",{"name":"og:url","content":"https://os.prozilla.dev/docs/reference/packages"}],["meta",{"name":"twitter:url","content":"https://os.prozilla.dev/docs/reference/packages"}],["meta",{"name":"og:locale","content":"en_US"}],["meta",{"name":"og:image","content":"https://os.prozilla.dev/docs/prozilla-os-title-banner.png"}],["meta",{"name":"twitter:image","content":"https://os.prozilla.dev/docs/prozilla-os-title-banner.png"}],["meta",{"name":"og:type","content":"website"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"reference/packages.md","filePath":"reference/packages.md"}'),i={name:"reference/packages.md"};function t(s,e,n,c,p,d){return o(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to “Packages”">​</a></h1><p>This is an overview of all packages related to ProzillaOS. Each package is published to the npm registry.</p><h2 id="bundle" tabindex="-1">Bundle <a class="header-anchor" href="#bundle" aria-label="Permalink to “Bundle”">​</a></h2><p>This bundle lets you quickly get started with ProzillaOS without the hassle of installing all packages individually.</p><ul><li><a href="./prozilla-os/"><code>prozilla-os</code></a>: A bundle containing <a href="/docs/reference/core/" data-symbol="@prozilla-os/core"><code>@prozilla-os/core</code></a>, <a href="/docs/reference/shared/" data-symbol="@prozilla-os/shared"><code>@prozilla-os/shared</code></a> and all <a href="#primary-applications">primary applications</a> of ProzillaOS.</li></ul><h2 id="libraries" tabindex="-1">Libraries <a class="header-anchor" href="#libraries" aria-label="Permalink to “Libraries”">​</a></h2><p>These libraries are different modules of ProzillaOS that can be installed separately. <a href="/docs/reference/core/" data-symbol="@prozilla-os/core"><code>@prozilla-os/core</code></a> and <a href="/docs/reference/shared/" data-symbol="@prozilla-os/shared"><code>@prozilla-os/shared</code></a> are also included in the <a href="/docs/reference/prozilla-os/" data-symbol="prozilla-os"><code>prozilla-os</code></a> bundle.</p><ul><li><a href="./core/"><code>@prozilla-os/core</code></a>: Core functionality of ProzillaOS, with React components, hooks and a router.</li><li><a href="./skins/"><code>@prozilla-os/skins</code></a>: Customizable skins for ProzillaOS that can override content and layout and dynamically load CSS.</li><li><a href="./shared/"><code>@prozilla-os/shared</code></a>: Common generic TypeScript functions and utilities (e.g., data manipulation, logging), not directly related to ProzillaOS.</li><li><a href="./dev-tools/"><code>@prozilla-os/dev-tools</code></a>: Tools for the development of anything related to ProzillaOS (e.g., ProzillaOS websites, ProzillaOS apps). Used extensively for the development of official ProzillaOS packages (e.g., shared configurations, testing utilities).</li></ul><h2 id="applications" tabindex="-1">Applications <a class="header-anchor" href="#applications" aria-label="Permalink to “Applications”">​</a></h2><h3 id="primary-applications" tabindex="-1">Primary applications <a class="header-anchor" href="#primary-applications" aria-label="Permalink to “Primary applications”">​</a></h3><p>These applications are included in the <a href="/docs/reference/prozilla-os/" data-symbol="prozilla-os"><code>prozilla-os</code></a> bundle.</p><ul><li><a href="./apps/file-explorer/"><code>@prozilla-os/file-explorer</code></a>: File explorer app</li><li><a href="./apps/terminal/"><code>@prozilla-os/terminal</code></a>: Terminal/shell app</li><li><a href="./apps/text-editor/"><code>@prozilla-os/text-editor</code></a>: Text editor app</li><li><a href="./apps/settings/"><code>@prozilla-os/settings</code></a>: Settings app</li><li><a href="./apps/media-viewer/"><code>@prozilla-os/media-viewer</code></a>: Media viewer app</li><li><a href="./apps/browser/"><code>@prozilla-os/browser</code></a>: Browser app</li><li><a href="./apps/calculator/"><code>@prozilla-os/calculator</code></a>: Calculator app</li><li><a href="./apps/app-center/"><code>@prozilla-os/app-center</code></a>: App center</li></ul><h3 id="secondary-applications" tabindex="-1">Secondary applications <a class="header-anchor" href="#secondary-applications" aria-label="Permalink to “Secondary applications”">​</a></h3><ul><li><a href="./apps/logic-sim/"><code>@prozilla-os/logic-sim</code></a>: Logic simulator app</li></ul><h3 id="external-applications" tabindex="-1">External applications <a class="header-anchor" href="#external-applications" aria-label="Permalink to “External applications”">​</a></h3><p>These applications are related to ProzillaOS and used in the demo, but their source code is hosted in a separate repository on GitHub.</p><ul><li><a href="https://github.com/prozilla-os/ProzillaOS-games/blob/main/packages/games/minesweeper" target="_blank" rel="noreferrer"><code>@prozilla-os/minesweeper</code></a>: Minesweeper clone</li><li><a href="https://github.com/prozilla-os/ProzillaOS-games/blob/main/packages/games/wordle" target="_blank" rel="noreferrer"><code>@prozilla-os/wordle</code></a>: Wordle clone</li><li><a href="https://github.com/prozilla-os/ProzillaOS-games/blob/main/packages/games/ball-maze" target="_blank" rel="noreferrer"><code>@prozilla-os/ball-maze</code></a>: 3D wooden ball maze game</li><li><a href="https://github.com/prozilla-os/Bliss-radio-app" target="_blank" rel="noreferrer"><code>@prozilla-os/bliss-radio</code></a>: Radio app</li></ul>',17)])])}const f=a(i,[["render",t]]);export{m as __pageData,f as default};
